def sha(text):
    return hashlib.sha256(text.encode()).hexdigest()


def functions(text):
    return {node.name: ast.dump(node, include_attributes=False)
        for node in ast.parse(text).body if isinstance(node, (ast.FunctionDef, ast.ClassDef))}


def pins(text):
    values = [ast.literal_eval(node.value) for node in ast.parse(text).body
        if isinstance(node, ast.Assign) and any(isinstance(t, ast.Name) and t.id == 'SOURCE_PINS'
            for t in node.targets)]
    if len(values) != 1:
        raise ValueError('Keep the one complete original scientific source registry')
    return values[0]


def validate(role, original, text):
    tree = ast.parse(text, filename=CHILDREN[role]['name'])
    compile(tree, CHILDREN[role]['name'], 'exec')
    for node in ast.walk(tree):
        if isinstance(node, ast.Dict):
            keys = [key.value for key in node.keys if isinstance(key, ast.Constant)
                and isinstance(key.value, (str, int, float))]
            if len(keys) != len(set(keys)):
                raise ValueError('Duplicate literal dictionary key')
    if any(line.rstrip() != line for line in text.splitlines()):
        raise ValueError('Trailing source whitespace')
    old, new = functions(original), functions(text)
    allowed = {'read_report'} if role == 'reader' else {'parse_args', 'main'}
    changed = [name for name in old if old[name] != new.get(name)]
    if set(changed)-allowed:
        raise ValueError('Unexpected complete original function change: '+str(changed))
    if role == 'driver':
        marker = '    def save_report():'
        if original[original.index(marker):] != text[text.index(marker):]:
            raise ValueError('The actual full scientific loop suffix changed')
        if pins(original) != pins(text):
            raise ValueError('The complete original scientific source registry changed')
    if sha(text) != CHILDREN[role]['sha256']:
        raise ValueError('The fully derived output differs from its complete published source identity')
    return changed


def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument('--parent-source-directory', type=Path, required=True)
    p.add_argument('--outdir', type=Path, required=True)
    args = p.parse_args()
    outputs = {}
    for role, record in PARENTS.items():
        original = (args.parent_source_directory/record['name']).read_text()
        if sha(original) != record['sha256']:
            raise ValueError('Use the entire exact parent '+record['name'])
        text = original
        for operation in STEPS[role]:
            if text.count(operation['old']) != 1:
                raise ValueError('The literal complete-source edit is not unique')
            text = text.replace(operation['old'], operation['new'], 1)
        changed = validate(role, original, text)
        outputs[role] = (text, changed)
    if args.outdir.exists():
        raise FileExistsError('Use a fresh pure-source output directory')
    args.outdir.mkdir(parents=True)
    for role, (text, changed) in outputs.items():
        path = args.outdir/CHILDREN[role]['name']
        path.write_text(text)
        print(json.dumps(dict(file=path.name, bytes=len(text.encode()), sha256=sha(text),
            changed_original_functions=changed, actual_AST_and_compile=True,
            scientific_execution=False), sort_keys=True))
    print('All original metric/Phase-I/J/Jtranspose/full-C/true-screen loops retained; no height selected.')


if __name__ == '__main__':
    main()
